import json, sys, ast, random, subprocess, math

random.seed(42)

def make_q(stem, opts, ans, ana, kn, mod, con):
    return {
        "stem": stem, "options": opts, "answer": ans,
        "analysis": ana, "knowledge": kn, "module": mod,
        "difficulty": "league", "target": "both", "concept": con
    }

QUESTIONS = []

# 读取现有33题
with open('/workspace/data/comp_batch_e_m3_eco_m4_gen.py', 'r') as f:
    content = f.read()
tree = ast.parse(content)
existing = []
for node in ast.walk(tree):
    if isinstance(node, ast.Assign):
        for t in node.targets:
            if isinstance(t, ast.Name) and t.id == 'QUESTIONS':
                for e in node.value.elts:
                    existing.append(ast.literal_eval(e))
QUESTIONS.extend(existing)
print(f'已有 {len(QUESTIONS)} 题')
sys.stdout.flush()

