from collections import Counter
concepts = Counter()
modules = Counter()
kn0 = Counter()
ans_count = Counter()
problems = []
for node in ast.walk(tree):
    if isinstance(node, ast.Assign):
        for t in node.targets:
            if isinstance(t, ast.Name) and t.id == 'QUESTIONS':
                for idx, elem in enumerate(node.value.elts):
                    try:
                        d = ast.literal_eval(elem)
                        concepts[d["concept"]] += 1
                        modules[d["module"]] += 1
                        kn0[d["knowledge"][0]] += 1
                        ans_count[d["answer"]] += 1
                        # 检查关键字段
                        if len(d["stem"]) < 15:
                            problems.append(f"题{idx+1} 题干过短: {len(d['stem'])}字")
                        if set(d["options"].keys()) != set("ABCD"):
                            problems.append(f"题{idx+1} 选项键错误")
                        for opt_k in "ABCD":
                            if len(d["options"][opt_k]) < 5:
                                problems.append(f"题{idx+1} 选项{opt_k}过短")
                        if d["answer"] not in "ABCD":
                            problems.append(f"题{idx+1} 答案非法: {d['answer']}")
                        if len(d["analysis"]) < 150:
                            problems.append(f"题{idx+1} 解析过短: {len(d['analysis'])}字")
                        if len(d["knowledge"]) != 3:
                            problems.append(f"题{idx+1} knowledge字段长度{len(d['knowledge'])}≠3")
                        if d["module"] not in ["module_3", "module_4"]:
                            problems.append(f"题{idx+1} module非法: {d['module']}")
                        if d["difficulty"] != "league":
                            problems.append(f"题{idx+1} difficulty非法")
                        if d["target"] != "both":
                            problems.append(f"题{idx+1} target非法")
                    except Exception as e:
                        problems.append(f"题{idx+1} 解析失败: {e}")

